  1→/**
  2→ * @fileoverview Tool registry and execution entry point.
  3→ *
  4→ * Maintains the in-process registry for built-in and custom tools, validates
  5→ * input arguments, executes handlers, and exposes OpenAI-compatible schemas.
  6→ *
  7→ * @module tools/registry
  8→ */
  9→
 10→import { z } from 'zod';
 11→import { ToolResult, ToolContext, DangerLevel } from './types.js';
 12→import { logger } from '../utils/logger.js';
 13→import { ToolInputSchemas, type ToolName } from '../validation/tools.js';
 14→
 15→// Import tool handlers
 16→import {
 17→  handleWorkspaceList,
 18→  handleWorkspaceSelect,
 19→  handleWorkspaceStatus,
 20→  handleWorkspaceCreate,
 21→  handleWorkspaceDelete,
 22→  handleFileDelete,
 23→  handleFolderDelete,
 24→  handleWorkspaceSync,
 25→  handleWorkspacePublish,
 26→  workspaceTools,
 27→} from './workspace.js';
 28→
 29→import {
 30→  handleTaskCreate,
 31→  handleTaskStatus,
 32→  handleTaskCancel,
 33→  handleTaskRespond,
 34→  taskTools,
 35→} from './task.js';
 36→
 37→import {
 38→  handleAskUser,
 39→  handleReportProgress,
 40→  interactionTools,
 41→} from './interaction.js';
 42→
 43→import {
 44→  handleGitHubPRCreate,
 45→  handleGitHubPRList,
 46→  handleGitHubPRView,
 47→  handleGitHubIssueCreate,
 48→  handleGitHubIssueList,
 49→  handleGitHubBranchCreate,
 50→  handleGitHubActionStatus,
 51→  handleGitHubSearchRepos,
 52→  githubTools,
 53→} from './github.js';
 54→
 55→import {
 56→  handlePMList,
 57→  handlePMView,
 58→  handlePMComment,
 59→  handlePMUpdate,
 60→  pmTools,
 61→} from './pm.js';
 62→
 63→import {
 64→  handleWebFetch,
 65→  handleWebSearch,
 66→  webTools,
 67→} from './web.js';
 68→
 69→import {
 70→  handleBrowserOpen,
 71→  handleBrowserSnapshot,
 72→  handleBrowserAction,
 73→  handleBrowserScreenshot,
 74→  browserTools,
 75→} from './browser.js';
 76→
 77→import {
 78→  handleWorkflowCreate,
 79→  handleWorkflowList,
 80→  handleWorkflowRun,
 81→  handleWorkflowDelete,
 82→  handleCronCreate,
 83→  handleCronList,
 84→  handleCronDelete,
 85→  handleCronRun,
 86→  handleAppRun,
 87→  handleAppTest,
 88→  handleBrowserTest,
 89→  workflowTools,
 90→} from './workflow.js';
 91→
 92→import { loadToolDefinition, buildToolSchema, CustomToolDefinition } from './loader.js';
 93→import { exec } from 'child_process';
 94→import util from 'util';
 95→const execPromise = util.promisify(exec);
 96→import chokidar from 'chokidar';
 97→import fs from 'fs';
 98→import { TOOLS_DIR } from '../config/paths.js';
 99→
100→// ============================================================================
101→// Internal Types
102→// ============================================================================
103→
104→/** Internal tool registration record used by the registry. */
105→export interface OrchestratorTool {
106→  /** Tool name */
107→  name: string; // broadened from ToolName for custom tools
108→  /** Tool description */
109→  description: string;
110→  /** Handler function */
111→  handler: (input: unknown, context?: ToolContext) => Promise<ToolResult>;
112→  /** Zod schema for validation */
113→  schema: z.ZodSchema;
114→  /** Safety level */
115→  danger?: DangerLevel;
116→  /** Is this a custom tool? */
117→  isCustom?: boolean;
118→}
119→
120→/** Async tool handler signature used by built-in and custom tools. */
121→export type ToolHandler = (input: unknown, context?: ToolContext) => Promise<ToolResult>;
122→
123→// ============================================================================
124→// Tool Registry Class
125→// ============================================================================
126→
127→export class ToolRegistry {
128→  private static instance: ToolRegistry | undefined;
129→  private tools: Map<string, OrchestratorTool> = new Map();
130→  private customToolFiles: Map<string, string> = new Map(); // filePath → toolName
131→  private customToolsDir: string;
132→  private watchers: ReturnType<typeof chokidar.watch>[] = [];
133→
134→  private constructor() {
135→    this.customToolsDir = TOOLS_DIR;
136→    this.registerBuiltins();
137→    this.initCustomTools();
138→  }
139→
140→  private initCustomTools() {
141→    // Ensure dir exists (or try to)
142→    if (!fs.existsSync(this.customToolsDir)) {
143→      // Ideally we create it, but constructor sync content... 
144→      // Async init pattern better, but singleton is sync accessed usually.
145→      // We'll set up watcher and let it fire on existing files if configured right.
146→    }
147→
148→    this.setupWatcher();
149→  }
150→
151→  private setupWatcher() {
152→    try {
153→      const watcher = chokidar.watch(this.customToolsDir, {
154→        ignored: /(^|[/\\])\../,
155→        persistent: true,
156→        depth: 0
157→      });
158→
159→      watcher.on('add', (f) => this.loadCustomTool(f));
160→      watcher.on('change', (f) => this.loadCustomTool(f));
161→      watcher.on('unlink', (f) => this.unloadCustomTool(f));
162→
163→      this.watchers.push(watcher);
164→    } catch (err) {
165→      logger.error('Failed to setup tool watcher', err);
166→    }
167→  }
168→
169→  private async loadCustomTool(filePath: string) {
170→    if (!filePath.endsWith('.json')) return;
171→    const previousName = this.customToolFiles.get(filePath);
172→
173→    try {
174→      const def = await loadToolDefinition(filePath);
175→      if (!def) {
176→        if (previousName) {
177→          this.tools.delete(previousName);
178→          this.customToolFiles.delete(filePath);
179→          logger.info(`Custom tool unloaded due to invalid definition: ${previousName}`);
180→        }
181→        return;
182→      }
183→
184→      if (previousName && previousName !== def.name) {
185→        this.tools.delete(previousName);
186→        logger.info(`Custom tool renamed: ${previousName} -> ${def.name}`);
187→      }
188→
189→      const schema = buildToolSchema(def);
190→      const handler = this.createShellHandler(def);
191→
192→      const tool: OrchestratorTool = {
193→        name: def.name,
194→        description: def.description,
195→        danger: def.danger,
196→        schema,
197→        handler,
198→        isCustom: true
199→      };
200→
201→      this.register(tool);
202→      this.customToolFiles.set(filePath, def.name);
203→      logger.info(`Custom tool loaded: ${tool.name}`);
204→    } catch (error) {
205→      logger.error(`Failed to reload custom tool: ${filePath}`, { error });
206→      if (previousName) {
207→        this.tools.delete(previousName);
208→        this.customToolFiles.delete(filePath);
209→        logger.info(`Custom tool unloaded after reload failure: ${previousName}`);
210→      }
211→    }
212→  }
213→
214→  private unloadCustomTool(filePath: string) {
215→    const toolName = this.customToolFiles.get(filePath);
216→    if (toolName) {
217→      this.tools.delete(toolName);
218→      this.customToolFiles.delete(filePath);
219→      logger.info(`Custom tool unloaded: ${toolName}`);
220→    }
221→  }
222→
223→  private createShellHandler(def: CustomToolDefinition): ToolHandler {
224→    return async (input: unknown) => {
225→      const params = input as Record<string, unknown>;
226→      let command = def.command;
227→
228→      // Template replacement: {{param}} with shell-safe escaping
229→      Object.keys(params).forEach(key => {
230→        const val = String(params[key]);
231→        // Escape single quotes and wrap in single quotes for shell safety
232→        const escaped = "'" + val.replace(/'/g, "'\\''") + "'";
233→        command = command.replace(new RegExp(`{{${key}}}`, 'g'), escaped);
234→      });
235→
236→      const MAX_SHELL_OUTPUT = 100_000;
237→      const start = Date.now();
238→      try {
239→        const cwd = def.cwd || process.cwd();
240→        const { stdout, stderr } = await execPromise(command, { cwd });
241→        const truncatedOutput = (stdout || stderr || 'Command executed successfully').slice(0, MAX_SHELL_OUTPUT);
242→
243→        return {
244→          success: true,
245→          output: truncatedOutput,
246→          duration: Date.now() - start
247→        };
248→      } catch (error) {
249→        const err = error as { stdout?: string; message?: string; stderr?: string };
250→        return {
251→          success: false,
252→          output: err.stdout || '',
253→          error: err.message || err.stderr || 'Unknown execution error',
254→          duration: Date.now() - start
255→        };
256→      }
257→    };
258→  }
259→
260→  public static getInstance(): ToolRegistry {
261→    if (!ToolRegistry.instance) {
262→      ToolRegistry.instance = new ToolRegistry();
263→    }
264→    return ToolRegistry.instance;
265→  }
266→
267→  /** Closes custom-tool watchers and releases watcher resources. */
268→  public async shutdown(): Promise<void> {
269→    for (const watcher of this.watchers) {
270→      await watcher.close();
271→    }
272→    this.watchers = [];
273→  }
274→
275→  /** Registers one tool definition (insert/replace by tool name). */
276→  public register(tool: OrchestratorTool): void {
277→    this.tools.set(tool.name, tool);
278→    logger.debug(`Registered tool: ${tool.name}`);
279→  }
280→
281→  /** Registers a dictionary of tools. */
282→  public registerAll(tools: Record<string, OrchestratorTool>): void {
283→    for (const tool of Object.values(tools)) {
284→      this.register(tool);
285→    }
286→  }
287→
288→  /** Returns one tool by name, if registered. */
289→  public get(name: string): OrchestratorTool | undefined {
290→    return this.tools.get(name);
291→  }
292→
293→  /** Returns all currently registered tools. */
294→  public list(): OrchestratorTool[] {
295→    return Array.from(this.tools.values());
296→  }
297→
298→  /** Returns registered tools in OpenAI function-calling format. */
299→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
300→  public toOpenAIFormat(toolNames?: string[]): any[] {
301→    const selected = toolNames && toolNames.length > 0
302→      ? toolNames
303→        .map((name) => this.tools.get(name))
304→        .filter((tool): tool is OrchestratorTool => !!tool)
305→      : Array.from(this.tools.values());
306→    const result = selected.map(tool => _mapToOpenAIFunction(tool));
307→
308→    // Log schemas once on first call for debugging
309→    if (!this._schemaLogged) {
310→      this._schemaLogged = true;
311→      for (const tool of result) {
312→        // eslint-disable-next-line @typescript-eslint/no-explicit-any
313→        const fn = (tool as any).function;
314→        logger.debug('Tool schema', {
315→          name: fn?.name,
316→          parameters: JSON.stringify(fn?.parameters),
317→        });
318→      }
319→    }
320→
321→    return result;
322→  }
323→
324→  private _schemaLogged = false;
325→
326→  /** Validates input and executes a registered tool handler by name. */
327→  public async execute(name: string, args: unknown, context?: ToolContext): Promise<ToolResult> {
328→    const tool = this.tools.get(name);
329→    logger.info(`ToolRegistry.execute called: ${name}`, { found: !!tool, hasHandler: !!tool?.handler });
330→    if (!tool) {
331→      return {
332→        success: false,
333→        output: `Tool '${name}' not found`,
334→        duration: 0
335→      };
336→    }
337→
338→    const startTime = Date.now();
339→    try {
340→      const autonomyLevel = context?.autonomyLevel ?? 'cautious';
341→
342→      // Enforce autonomy policy before schema/handler execution.
343→      // This is a hard safety layer independent of prompt behavior.
344→      if (tool.danger === DangerLevel.DANGEROUS) {
345→        if (autonomyLevel === 'supervised') {
346→          return {
347→            success: false,
348→            output: `Safety policy blocked dangerous tool '${name}' in supervised mode. Request explicit operator intervention or switch autonomy level.`,
349→            duration: Date.now() - startTime,
350→          };
351→        }
352→        if (autonomyLevel === 'cautious' && !hasExplicitConfirmation(args)) {
353→          return {
354→            success: false,
355→            output: `Tool '${name}' requires manual confirmation in Cautious Mode. You MUST use the 'ask_user' tool to request permission from the operator explaining exactly what you intend to do. If they approve, retry this action with 'confirm: true'.`,
356→            duration: Date.now() - startTime,
357→          };
358→        }
359→      }
360→
361→      // Validate args with Zod safeParse — lets the LLM self-correct bad arguments
362→      const validation = tool.schema.safeParse(args);
363→      if (!validation.success) {
364→        const issues = validation.error.issues
365→          .map((i) => `${i.path.join('.')}: ${i.message}`)
366→          .join('; ');
367→        logger.warn(`Tool validation failed: ${name}`, { issues });
368→        return {
369→          success: false,
370→          output: `Validation error for tool '${name}': ${issues}. Please fix the arguments and try again.`,
371→          duration: Date.now() - startTime
372→        };
373→      }
374→
375→      const result = await tool.handler(validation.data, context);
376→      // Ensure duration is present if tool doesn't provide it
377→      if (result.duration === undefined) {
378→        result.duration = Date.now() - startTime;
379→      }
380→      return result;
381→    } catch (error) {
382→      logger.error(`Tool execution failed: ${name}`, { error });
383→      return {
384→        success: false,
385→        output: `Error executing tool '${name}': ${error instanceof Error ? error.message : String(error)}`,
386→        duration: Date.now() - startTime
387→      };
388→    }
389→  }
390→
391→  private registerBuiltins(): void {
392→    const builtins: Record<string, { h: ToolHandler; s: z.ZodSchema; d: DangerLevel }> = {
393→      // WORKSPACE
394→      workspace_list: { h: handleWorkspaceList, s: ToolInputSchemas.workspace_list, d: DangerLevel.SAFE },
395→      workspace_select: { h: handleWorkspaceSelect, s: ToolInputSchemas.workspace_select, d: DangerLevel.SAFE },
396→      workspace_status: { h: handleWorkspaceStatus, s: ToolInputSchemas.workspace_status, d: DangerLevel.SAFE },
397→      workspace_create: { h: handleWorkspaceCreate, s: ToolInputSchemas.workspace_create, d: DangerLevel.MODERATE },
398→      workspace_delete: { h: handleWorkspaceDelete, s: ToolInputSchemas.workspace_delete, d: DangerLevel.DANGEROUS },
399→      file_delete: { h: handleFileDelete, s: ToolInputSchemas.file_delete, d: DangerLevel.DANGEROUS },
400→      folder_delete: { h: handleFolderDelete, s: ToolInputSchemas.folder_delete, d: DangerLevel.DANGEROUS },
401→      workspace_sync: { h: handleWorkspaceSync, s: ToolInputSchemas.workspace_sync, d: DangerLevel.MODERATE },
402→      workspace_publish: { h: handleWorkspacePublish, s: ToolInputSchemas.workspace_publish, d: DangerLevel.MODERATE },
403→
404→      // TASK
405→      task_create: { h: handleTaskCreate, s: ToolInputSchemas.task_create, d: DangerLevel.MODERATE },
406→      task_status: { h: handleTaskStatus, s: ToolInputSchemas.task_status, d: DangerLevel.SAFE },
407→      task_cancel: { h: handleTaskCancel, s: ToolInputSchemas.task_cancel, d: DangerLevel.MODERATE },
408→      task_respond: { h: handleTaskRespond, s: ToolInputSchemas.task_respond, d: DangerLevel.SAFE },
409→
410→      // INTERACTION
411→      ask_user: { h: handleAskUser, s: ToolInputSchemas.ask_user, d: DangerLevel.SAFE },
412→      report_progress: { h: handleReportProgress, s: ToolInputSchemas.report_progress, d: DangerLevel.SAFE },
413→
414→      // GITHUB
415→      github_pr_create: { h: handleGitHubPRCreate, s: ToolInputSchemas.github_pr_create, d: DangerLevel.MODERATE },
416→      github_pr_list: { h: handleGitHubPRList, s: ToolInputSchemas.github_pr_list, d: DangerLevel.SAFE },
417→      github_pr_view: { h: handleGitHubPRView, s: ToolInputSchemas.github_pr_view, d: DangerLevel.SAFE },
418→      github_issue_create: { h: handleGitHubIssueCreate, s: ToolInputSchemas.github_issue_create, d: DangerLevel.MODERATE },
419→      github_issue_list: { h: handleGitHubIssueList, s: ToolInputSchemas.github_issue_list, d: DangerLevel.SAFE },
420→      github_branch_create: { h: handleGitHubBranchCreate, s: ToolInputSchemas.github_branch_create, d: DangerLevel.MODERATE },
421→      github_action_status: { h: handleGitHubActionStatus, s: ToolInputSchemas.github_action_status, d: DangerLevel.SAFE },
422→      github_search_repos: { h: handleGitHubSearchRepos, s: ToolInputSchemas.github_search_repos, d: DangerLevel.SAFE },
423→
424→      // PM
425→      pm_list: { h: handlePMList, s: ToolInputSchemas.pm_list, d: DangerLevel.SAFE },
426→      pm_view: { h: handlePMView, s: ToolInputSchemas.pm_view, d: DangerLevel.SAFE },
427→      pm_comment: { h: handlePMComment, s: ToolInputSchemas.pm_comment, d: DangerLevel.MODERATE },
428→      pm_update: { h: handlePMUpdate, s: ToolInputSchemas.pm_update, d: DangerLevel.MODERATE },
429→
430→      // WEB
431→      web_fetch: { h: handleWebFetch, s: ToolInputSchemas.web_fetch, d: DangerLevel.SAFE },
