452→
453→    for (const [name, meta] of Object.entries(builtins)) {
454→      const wTools = workspaceTools as Record<string, { description: string }>;
455→      const tTools = taskTools as Record<string, { description: string }>;
456→      const iTools = interactionTools as Record<string, { description: string }>;
457→      const gTools = githubTools as Record<string, { description: string }>;
458→      const pTools = pmTools as Record<string, { description: string }>;
459→      const webT = webTools as Record<string, { description: string }>;
460→      const brT = browserTools as Record<string, { description: string }>;
461→      const wfT = workflowTools as Record<string, { description: string }>;
462→
463→      const description = (wTools[name] || tTools[name] || iTools[name] || gTools[name] || pTools[name] || webT[name] || brT[name] || wfT[name])?.description || 'No description';
464→      logger.info(`Registering builtin tool: ${name}`, { hasHandler: !!meta.h });
465→
466→      this.register({
467→        name: name as ToolName,
468→        description,
469→        handler: meta.h,
470→        schema: meta.s,
471→        danger: meta.d
472→      });
473→    }
474→  }
475→}
