481→function hasExplicitConfirmation(args: unknown): boolean {
482→  if (!args || typeof args !== 'object') return false;
483→  const record = args as Record<string, unknown>;
484→  return record.confirm === true;
485→}
486→
487→function _mapToOpenAIFunction(tool: OrchestratorTool): Record<string, unknown> {
488→  return {
489→    type: 'function',
490→    function: {
491→      name: tool.name,
492→      description: tool.description,
493→      parameters: zodToJsonSchema(tool.schema),
494→    },
495→  };
496→}
497→
498→function zodToJsonSchema(schema: z.ZodSchema): Record<string, unknown> {
499→  // Zod v4: use .type and .def instead of ._def.typeName
500→  // eslint-disable-next-line @typescript-eslint/no-explicit-any
501→  const s = schema as any;
502→
503→  if (s.type === 'object' && s.def?.shape) {
504→    const shape = s.def.shape;
505→    const properties: Record<string, unknown> = {};
506→    const required: string[] = [];
507→
508→    for (const [key, value] of Object.entries(shape)) {
509→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
510→      const field = value as any;
511→
512→      // Use Zod v4's built-in isOptional() method
513→      const isOptional = typeof field.isOptional === 'function' ? field.isOptional() : false;
514→
515→      // Unwrap wrapper types to get the core type
516→      const innerSchema = unwrapZodType(field);
517→      properties[key] = zodTypeToJsonSchema(innerSchema, field);
518→
519→      if (!isOptional) required.push(key);
520→    }
521→
522→    const result: Record<string, unknown> = { type: 'object', properties };
523→    if (required.length > 0) result.required = required;
524→    return result;
525→  }
526→  return { type: 'object', properties: {} };
527→}
528→
529→/** Unwraps default/optional/nullable wrappers to reach core Zod type. */
530→// eslint-disable-next-line @typescript-eslint/no-explicit-any
531→function unwrapZodType(schema: any): any {
532→  let current = schema;
533→  while (current) {
534→    const type = current.type ?? current.def?.type;
535→    if (type === 'default' || type === 'optional' || type === 'nullable') {
536→      current = current.def?.innerType ?? current._def?.innerType;
537→    } else {
538→      return current;
539→    }
540→  }
541→  return schema;
542→}
543→
544→/** Converts one Zod field schema into JSON-schema-like descriptor. */
545→// eslint-disable-next-line @typescript-eslint/no-explicit-any
546→function zodTypeToJsonSchema(innerSchema: any, outerSchema?: any): Record<string, unknown> {
547→  const base: Record<string, unknown> = {};
548→
549→  // In Zod v4, .description is a direct property, also available via .meta()
550→  const desc = outerSchema?.description ?? innerSchema?.description;
551→  if (desc) base.description = desc;
552→
553→  const type = innerSchema?.type ?? innerSchema?.def?.type;
554→
555→  switch (type) {
556→    case 'string': return { ...base, type: 'string' };
557→    case 'number': return { ...base, type: 'number' };
558→    case 'boolean': return { ...base, type: 'boolean' };
559→    case 'enum': {
560→      // Zod v4: enum entries are in .def.entries as { key: value } or .values as array
561→      const entries = innerSchema.def?.entries;
562→      const values = entries ? Object.values(entries) : (innerSchema.values ?? innerSchema.options);
563→      return values ? { ...base, type: 'string', enum: values } : { ...base, type: 'string' };
564→    }
565→    case 'array': {
566→      const itemSchema = innerSchema.def?.element ?? innerSchema.def?.type;
567→      return { ...base, type: 'array', items: itemSchema ? zodTypeToJsonSchema(unwrapZodType(itemSchema)) : { type: 'string' } };
568→    }
569→    default: return { ...base, type: 'string' };
570→  }
571→}
572→
573→export const getToolRegistry = () => ToolRegistry.getInstance();
