/**
 * @fileoverview Core message-processing loop for the Fetch bridge.
 *
 * Responsibilities:
 * - Run the primary LLM turn with full tool access
 * - Execute tool-call loops with retry/backoff and circuit breaker behavior
 * - Build context/prompt input from session, identity, skills, and workspace state
 * - Provide task framing and bounded progress-message rewriting helpers
 *
 * @module agent/core
 * @see {@link ToolRegistry} Tool registration and execution
 * @see {@link IdentityManager} System prompt assembly
 */

import OpenAI from 'openai';
import { Session, PromptMode, AgentRunPhase, AgentTurnTelemetry, ToolTelemetry } from '../session/types.js';
import { logger } from '../utils/logger.js';
import type { ResponseEnvelope } from './envelope.js';
import {
  buildTaskFramePrompt,
  buildContextSection,
} from './prompts.js';
import { buildCapabilitySummary, buildToolInventory } from './capability-cards.js';
import {
  classifyIntent,
  evaluateIntentGate,
  selectToolNamesForTurn,
  shouldUseMinimalMode,
  wantsFullInventory,
  type ResponseIntent,
  getResponsePreferences,
  parsePreferenceUpdate,
} from './response-policy.js';
import { getToolRegistry } from '../tools/registry.js';
import { getSessionManager } from '../session/manager.js';
import { generateRepoMap } from '../workspace/repo-map.js';
import { getIdentityManager } from '../identity/manager.js';
import { getSkillManager } from '../skills/manager.js';
import { env } from '../config/env.js';
import { pipeline } from '../config/pipeline.js';

// =============================================================================
// TYPES
// =============================================================================

/**
 * Agent response
 */
export interface AgentResponse {
  /** Text response to user */
  text: string;
  /** Structured response envelope for unified final rendering */
  envelope?: ResponseEnvelope;
  /** Detected response intent used by renderer behavior */
  intent?: ResponseIntent;
  /** Tool calls made (for logging) */
  toolCalls?: ToolCallRecord[];
  /** Turn-level runtime telemetry */
  telemetry?: AgentTurnTelemetry;
  /** Selected prompt mode for this turn */
  promptMode?: PromptMode;
  /** Whether a task was started */
  taskStarted?: boolean;
  /** Task ID if started */
  taskId?: string;
}

/**
 * Tool call record
 */
export interface ToolCallRecord {
  name: string;
  args: Record<string, unknown>;
  result: unknown;
}

/** Optional controls and hooks for one processMessage turn. */
export interface AgentProcessOptions {
  promptMode?: PromptMode;
  runId?: string;
  abortSignal?: AbortSignal;
  onLifecycle?: (
    phase: AgentRunPhase,
    details?: { toolName?: string; toolCallCount?: number; promptMode?: PromptMode; error?: string }
  ) => Promise<void> | void;
}

// =============================================================================
// CONSTANTS
// =============================================================================

const MODEL = env.AGENT_MODEL;
const MAX_TOOL_CALLS = pipeline.maxToolCalls;
const MAX_CONSECUTIVE_ERRORS = pipeline.circuitBreakerThreshold;
const ERROR_BACKOFF_MS = pipeline.circuitBreakerBackoff;
const REDACTED = '[REDACTED]';
const SENSITIVE_ARG_KEYS = [
  'token',
  'apiKey',
  'apikey',
  'secret',
  'password',
  'authorization',
  'auth',
  'cookie',
  'privateKey',
  'clientSecret',
];

function isSensitiveKey(key: string): boolean {
  const normalized = key.toLowerCase();
  return SENSITIVE_ARG_KEYS.some((needle) => normalized.includes(needle.toLowerCase()));
}

function sanitizeForPersistence(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeForPersistence(item));
  }
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};

/**
 * @fileoverview Environment variable access and startup validation.
 *
 * This module provides:
 * - Zod schema validation for required/optional env vars
 * - runtime `env` proxy for live `process.env` reads with defaults
 * - exported `VERSION` value resolved from the project version source
 *
 * @module config/env
 */

import { z } from 'zod';

// ============================================================================
// Schema
// ============================================================================

const EnvSchema = z.object({
  // Required
  OPENROUTER_API_KEY: z.string().min(1, 'OPENROUTER_API_KEY is required'),
  OWNER_PHONE_NUMBER: z.string().min(1, 'OWNER_PHONE_NUMBER is required'),

  // Models
  AGENT_MODEL: z.string().default('openai/gpt-4o-mini'),
  SUMMARY_MODEL: z.string().default('openai/gpt-4o-mini'),
  VISION_MODEL: z.string().default('openai/gpt-4o-mini'),
  WHISPER_MODEL: z.string().default('/app/models/ggml-tiny.bin'),

  // Paths
  WORKSPACE_ROOT: z.string().default('/workspace'),
  DATA_DIR: z.string().optional(),
  DATABASE_PATH: z.string().optional(),
  TASKS_DB_PATH: z.string().optional(),

  // Logging
  LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('debug'),

  // Security
  ADMIN_TOKEN: z.string().optional(),
  TRUSTED_PHONE_NUMBERS: z.string().optional(),

  // Harness Feature Flags
  ENABLE_COPILOT: z.string().transform(val => val === 'true').optional().default(true),
  ENABLE_CLAUDE: z.string().transform(val => val === 'true').optional().default(false),
  ENABLE_GEMINI: z.string().transform(val => val === 'true').optional().default(false),
  ENABLE_OPENCODE: z.string().transform(val => val === 'true').optional().default(false),
  ENABLE_CODEX: z.string().transform(val => val === 'true').optional().default(false),

  // Web / Browser Feature Flags
  ENABLE_WEB_FETCH: z.string().transform(val => val === 'true').optional().default(true),
  ENABLE_WEB_SEARCH: z.string().transform(val => val === 'true').optional().default(true),
  ENABLE_BROWSER: z.string().transform(val => val === 'true').optional().default(false),

  // Agent Models (Optional overrides)
  COPILOT_MODEL: z.string().optional(),
  CLAUDE_MODEL: z.string().optional(),
  GEMINI_MODEL: z.string().optional(),
  OPENCODE_MODEL: z.string().optional(),
  CODEX_MODEL: z.string().optional(),

  // Harness Auth
  ANTHROPIC_API_KEY: z.string().optional(),
  GEMINI_API_KEY: z.string().optional(),
  OPENCODE_API_KEY: z.string().optional(),
  CODEX_API_KEY: z.string().optional(),
  OPENAI_API_KEY: z.string().optional(),
  GH_TOKEN: z.string().optional(),
  LINEAR_API_KEY: z.string().optional(),
  JIRA_API_KEY: z.string().optional(),
  JIRA_DOMAIN: z.string().optional(),
  JIRA_EMAIL: z.string().optional(),
});

// ============================================================================
// Defaults
// ============================================================================

const DEFAULTS: Partial<Record<string, string>> = {
  AGENT_MODEL: 'openai/gpt-4o-mini',
  SUMMARY_MODEL: 'openai/gpt-4o-mini',
  VISION_MODEL: 'openai/gpt-4o-mini',
  WHISPER_MODEL: '/app/models/ggml-tiny.bin',
  WORKSPACE_ROOT: '/workspace',
  LOG_LEVEL: 'debug',
};

// ============================================================================
// Version
// ============================================================================

import { getVersion } from '../utils/version.js';

/** Application version string used by user-facing command/format output. */
export const VERSION = getVersion();

// ============================================================================
// Exports
// ============================================================================

type EnvConfig = z.infer<typeof EnvSchema>;
type EnvShape = typeof EnvSchema.shape;

/**
 * Environment accessor proxy.
 *
 * Reads `process.env` on each property access and applies defaults from
 * `DEFAULTS` when a value is unset. This keeps runtime config reloads and
 * test-time overrides visible without re-importing the module.
 */
export const env = new Proxy({} as EnvConfig, {
  get(_target, prop: string) {
    const val = process.env[prop];
    if (val !== undefined && val !== '') return val;
    return DEFAULTS[prop];
  },
});

// Load .env file if present
import dotenv from 'dotenv';
// Keep .env as the source of truth for runtime config inside the container.
dotenv.config({ override: true });

/**
 * Validate environment values against `EnvSchema`.
 *
 * @returns Validation status and missing/invalid keys
 */
export function validateEnv(): { valid: boolean; missing: string[] } {
  // Construct an object with all values (process.env + DEFAULTS)
  const envVars = Object.keys(EnvSchema.shape).reduce((acc, key) => {
    const val = process.env[key];
    if (val !== undefined && val !== '') {
      acc[key] = val;
    } else if (key in DEFAULTS) {
      acc[key] = DEFAULTS[key];
    }
    return acc;
  }, {} as Record<string, any>);

  const result = EnvSchema.safeParse(envVars);

  if (!result.success) {
    // Collect missing paths from Zod issues
    const missing = result.error.issues.map((i) => i.path.join('.'));
    return { valid: false, missing };
  }

  return { valid: true, missing: [] };
}

/**
 * Validate runtime env updates before applying them to `process.env`.
 *
 * Unknown keys and values that fail the declared schema are rejected.
 */
export function validateRuntimeEnvUpdates(
  updates: Record<string, string>
): { valid: boolean; invalid: Array<{ key: string; reason: string }> } {
  const invalid: Array<{ key: string; reason: string }> = [];
  const shape = EnvSchema.shape as EnvShape;

  for (const [key, value] of Object.entries(updates)) {
    const schema = shape[key as keyof EnvShape];
    if (!schema) {
      invalid.push({ key, reason: 'Unknown environment key' });
      continue;
    }

    const result = schema.safeParse(value);
    if (!result.success) {
      invalid.push({
        key,
        reason: result.error.issues[0]?.message ?? 'Invalid value',
      });
    }
  }

  return { valid: invalid.length === 0, invalid };
}

/**
 * @fileoverview Zod schemas for all orchestrator tool inputs.
 *
 * This file is the canonical source for accepted tool names and arguments.
 *
 * @module validation/tools
 */

import { z } from 'zod';
import {
  WorkspaceNameSchema,
  TaskIdSchema,
  TimeoutSchema,
  GoalSchema,
  QuestionSchema,
  ResponseSchema,
  ProgressMessageSchema,
  PercentageSchema,
  SafePathSchema,
  DEFAULT_TIMEOUT_MS,
} from './common.js';

// ============================================================================
// Agent Schemas
// ============================================================================

/** Allowed agent identifiers for `task_create`. */
export const AGENT_SELECTION_VALUES = ['copilot', 'gemini', 'claude', 'opencode', 'codex', 'auto'] as const;

/** Allowed agent identifiers for `task_create`. */
export const AgentSelectionSchema = z.enum(
  AGENT_SELECTION_VALUES,
  {
    error: 'Agent must be one of: copilot, gemini, claude, opencode, codex, auto',
  }
);

// ============================================================================
// Project Template Schemas
// ============================================================================

/** Allowed workspace templates for `workspace_create`. */
export const ProjectTemplateSchema = z.enum([
  'empty',      // Just creates the directory
  'node',       // package.json + basic structure
  'python',     // requirements.txt + basic structure
  'rust',       // Cargo.toml + basic structure
  'go',         // go.mod + basic structure
  'react',      // Vite React template
  'next',       // Next.js template

