20→    Task: allTools.filter((name) => name.startsWith('task_')),
21→    Interaction: allTools.filter((name) => name === 'ask_user' || name === 'report_progress'),
22→    GitHub: allTools.filter((name) => name.startsWith('github_')),
23→    Web: allTools.filter((name) => name.startsWith('web_')),
24→    Browser: allTools.filter((name) => name.startsWith('browser_') && name !== 'browser_test'),
25→    WorkflowRuntime: allTools.filter((name) => name.startsWith('workflow_') || name.startsWith('cron_') || name === 'app_run' || name === 'app_test' || name === 'browser_test'),
26→  };
27→}
